#!/usr/bin/env node

/**
 * ULS Unified CLI
 * 
 * Usage:
 *   uls -g component ComponentName
 *   uls init
 *   uls sync
 *   etc.
 */

const { spawn } = require('child_process');
const path = require('path');

const args = process.argv.slice(2);

// Debug: log args (can be enabled for troubleshooting)
// console.log('Debug - Received args:', JSON.stringify(args));

if (args.length === 0) {
  console.log(`
ULS CLI - Unified command interface

Usage:
  uls -g component <ComponentName>    Generate a new custom component
  uls -d component <ComponentName>    Delete a custom component
  uls init                            Initialize ULS in your project
  uls sync                            Sync ULS updates
  uls override                        Create override files
  uls passthrough                     Create passthrough helpers
  uls create-custom-demo              Create custom demo page
  uls create-custom-demo-type         Create custom demo type
  uls create-custom-component-demo    Create demo page for custom component
  uls register-demo                   Register component demo in navigation

Examples:
  uls -g component MyButton
  uls -d component MyButton
  uls init
  uls sync
  uls create-custom-component-demo CustomCard
  uls register-demo CustomCard
`);
  process.exit(0);
}

// Handle -g component and -d component commands
// Need to handle multiple cases:
// 1. Normal: args = ["-g", "component", "ComponentName"] or ["-d", "component", "ComponentName"]
// 2. Quoted: args = ["-g component", "ComponentName"] (npx sometimes does this)
// 3. Single arg: args = ["-g component ComponentName"]

let componentName = null;
let isDeleteCommand = false;

// Check for delete command first
if (args.length >= 3 && args[0] === '-d' && args[1] === 'component') {
  componentName = args[2];
  isDeleteCommand = true;
} else if (args.length >= 2 && String(args[0]).trim().startsWith('-d')) {
  const firstArg = String(args[0]).trim().replace(/\s+/g, ' ');
  if (firstArg === '-d component' || (firstArg.startsWith('-d') && firstArg.includes('component'))) {
    componentName = args[1];
    isDeleteCommand = true;
  }
} else if (args.length >= 1 && args[0].startsWith('-d')) {
  const parts = args[0].split(/\s+/);
  if (parts.length >= 3 && parts[0] === '-d' && parts[1] === 'component') {
    componentName = parts[2];
    isDeleteCommand = true;
  } else if (parts.length === 2 && parts[0] === '-d' && parts[1] === 'component' && args[1]) {
    componentName = args[1];
    isDeleteCommand = true;
  }
}

// Check for generate command if not delete
if (!isDeleteCommand) {
  // Case 1: Normal parsing: args = ["-g", "component", "ComponentName"]
  if (args.length >= 3 && args[0] === '-g' && args[1] === 'component') {
    componentName = args[2];
  }
  // Case 2: Quoted parsing: args = ["-g component", "ComponentName"]
  else if (args.length >= 2) {
    const firstArg = String(args[0]).trim().replace(/\s+/g, ' '); // Normalize whitespace
    // Check if first arg matches "-g component" pattern
    // This handles: "-g component", "-g  component" (double space), etc.
    if (firstArg === '-g component' || 
        (firstArg.startsWith('-g') && firstArg.includes('component'))) {
      // Extract component name from args[1]
      componentName = args[1];
    }
  }
  // Case 3: Single arg: args = ["-g component ComponentName"]
  else if (args.length >= 1 && args[0].startsWith('-g')) {
    // Try to parse "-g component ComponentName" format
    const parts = args[0].split(/\s+/);
    if (parts.length >= 3 && parts[0] === '-g' && parts[1] === 'component') {
      componentName = parts[2];
    } else if (parts.length === 2 && parts[0] === '-g' && parts[1] === 'component' && args[1]) {
      // "-g component" as first arg, ComponentName as second
      componentName = args[1];
    }
  }
}

// If we found a component name, execute the appropriate command
if (componentName) {
  componentName = componentName.trim();
  if (componentName === '') {
    console.error('❌ Error: Component name is required');
    console.log(`\nUsage: uls ${isDeleteCommand ? '-d' : '-g'} component <ComponentName>`);
    console.log(`Example: uls ${isDeleteCommand ? '-d' : '-g'} component MyButton`);
    process.exit(1);
  }
  
  // Determine which script to call
  const scriptName = isDeleteCommand ? 'delete-component.js' : 'create-component.js';
  const scriptPath = path.resolve(__dirname, '..', 'components', scriptName);
  
  // Verify script exists
  const fs = require('fs');
  if (!fs.existsSync(scriptPath)) {
    console.error(`❌ Error: ${isDeleteCommand ? 'Delete' : 'Component generator'} script not found at: ${scriptPath}`);
    console.error(`   Current __dirname: ${__dirname}`);
    process.exit(1);
  }
  
  const child = spawn('node', [scriptPath, componentName], {
    stdio: 'inherit',
    cwd: process.cwd()
  });
  
  child.on('exit', (code) => {
    process.exit(code || 0);
  });
  return;
}

// Handle case where -g or -d is used but component is missing or malformed
if (!componentName && args.length >= 1) {
  const firstArg = String(args[0]).trim();
  if (firstArg === '-g' || firstArg.startsWith('-g')) {
    console.error('❌ Error: Invalid usage of -g flag');
    console.log('\nUsage: uls -g component <ComponentName>');
    console.log('Example: uls -g component MyButton');
    console.log(`\nReceived: ${args.join(' ')}`);
    process.exit(1);
  } else if (firstArg === '-d' || firstArg.startsWith('-d')) {
    console.error('❌ Error: Invalid usage of -d flag');
    console.log('\nUsage: uls -d component <ComponentName>');
    console.log('Example: uls -d component MyButton');
    console.log(`\nReceived: ${args.join(' ')}`);
    process.exit(1);
  }
}

// Route other commands to existing scripts
const commandMap = {
  'init': path.join(__dirname, '..', 'init', 'create-init.js'),
  'sync': path.join(__dirname, '..', 'build', 'uls-sync.js'),
  'override': path.join(__dirname, '..', 'init', 'create-override.js'),
  'passthrough': path.join(__dirname, '..', 'init', 'create-passthrough.js'),
  'create-custom-demo': path.join(__dirname, '..', 'components', 'create-custom-demo.mjs'),
  'create-custom-demo-type': path.join(__dirname, '..', 'components', 'create-custom-demo-type.mjs'),
  'create-custom-component-demo': path.join(__dirname, '..', 'components', 'create-custom-component-demo.mjs'),
  'register-demo': path.join(__dirname, '..', 'components', 'register-uls-component-demo.mjs'),
  'update-config': path.join(__dirname, '..', 'init', 'update-config.mjs'),
  'config': path.join(__dirname, '..', 'init', 'update-config.mjs')  // Alias for update-config
};

const command = args[0];
const script = commandMap[command];

if (script) {
  const scriptPath = script; // Already contains full path from commandMap
  const scriptArgs = args.slice(1);
  
  // Debug: log what we're passing (can be removed later)
  // console.log('Passing args to script:', scriptArgs);
  
  const child = spawn('node', [scriptPath, ...scriptArgs], {
    stdio: 'inherit',
    cwd: process.cwd(),
    shell: false
  });
  
  child.on('exit', (code) => {
    process.exit(code || 0);
  });
} else {
  // Better error message - show what was received
  const receivedCommand = args.length > 0 ? args.join(' ') : '(none)';
  console.error(`❌ Unknown command: ${receivedCommand}`);
  console.log('\nAvailable commands:');
  console.log('  uls -g component <ComponentName>    Generate a custom component');
  console.log('  uls -d component <ComponentName>    Delete a custom component');
  Object.keys(commandMap).forEach(cmd => {
    console.log(`  uls ${cmd}`);
  });
  console.log('\nNote: For component operations, use:');
  console.log('  uls -g component <ComponentName>    to generate');
  console.log('  uls -d component <ComponentName>    to delete');
  console.log('Example: uls -g component MyButton');
  console.log('Example: uls -d component MyButton');
  process.exit(1);
}

